package com.thangit.boardinghouse.service;

import static com.thangit.boardinghouse.service.CommunicationService.*;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

@Service
public class CommunicationJobs {
 @org.springframework.beans.factory.annotation.Value("${app.communications.reminder-email.enabled:false}")
 boolean emailReminders;
 final JdbcClient db;final CommunicationService service;final CommunicationSender external;
 public CommunicationJobs(JdbcClient db,CommunicationService service,CommunicationSender external){this.db=db;this.service=service;this.external=external;}
 record Source(String event,String type,long id,long property,Long room,Long tenant,Long assignee,LocalDateTime at,LocalDateTime created,String key,String code,String category,String title){}
 static LocalDateTime datetime(Object o){if(o==null)return null;if(o instanceof java.sql.Timestamp t)return t.toLocalDateTime();if(o instanceof java.sql.Date d)return d.toLocalDate().atStartOfDay();if(o instanceof LocalDateTime t)return t;if(o instanceof LocalDate d)return d.atStartOfDay();return LocalDateTime.parse(o.toString().replace(' ','T'));}
 static Long nullable(Map<String,Object>r,String k){return r.get(k)==null?null:number(r,k);}
 List<Source> sources(long property,String event){return sources(property,event,null);}
 List<Source> sources(long property,String event,Long sourceId){
  String sql;String type,category;switch(event){
   case "INVOICE_ISSUED","PAYMENT_OPEN","INVOICE_BEFORE_DUE","INVOICE_DUE","INVOICE_OVERDUE"->{type="INVOICE";category="INVOICE";String at=switch(event){case "INVOICE_ISSUED"->"COALESCE(i.issued_at,CAST(i.issue_date AS DATETIME))";case "PAYMENT_OPEN"->"i.payment_available_from";default->"i.due_date";};sql="SELECT i.id,i.room_id,i.tenant_id,NULL assigned,"+at+" at_time,COALESCE(i.issued_at,i.created_at) created_at,i.code,CONCAT(i.due_date,'|',i.payment_available_from) source_key FROM invoices i WHERE i.property_id=:property AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED','PAID') AND i.remaining_amount>0";}
   case "PAYMENT_CONFIRMED"->{type="INVOICE";category="PAYMENT";sql="SELECT py.invoice_id id,i.room_id,i.tenant_id,NULL assigned,py.paid_at at_time,py.paid_at created_at,i.code,CONCAT('payment-',py.id) source_key FROM payments py JOIN invoices i ON i.id=py.invoice_id WHERE i.property_id=:property AND py.status='CONFIRMED' AND py.transaction_type='PAYMENT'";}
   case "PAYMENT_FAILED"->{type="INVOICE";category="PAYMENT";sql="SELECT gs.invoice_id id,i.room_id,i.tenant_id,NULL assigned,gs.completed_at at_time,gs.completed_at created_at,CONCAT(i.code,' · ',gs.provider,' · ',gs.environment) code,CONCAT('gateway-failed-',gs.id) source_key FROM gateway_sessions gs JOIN invoices i ON i.id=gs.invoice_id WHERE i.property_id=:property AND gs.status IN ('FAILED','CANCELLED','EXPIRED') AND gs.provider<>'SIMULATED' AND i.status NOT IN ('DRAFT','PENDING_REVIEW','PAID','CANCELLED') AND i.remaining_amount>0";}
   case "CONTRACT_CREATED","CONTRACT_CONFIRMED"->{type="CONTRACT";category="CONTRACT";boolean confirmed=event.equals("CONTRACT_CONFIRMED");sql=confirmed?"SELECT c.id,c.room_id,c.tenant_id,NULL assigned,MAX(rc.confirmed_at) at_time,MAX(rc.confirmed_at) created_at,c.code,CONCAT('confirmed-',cv.id) source_key FROM contracts c JOIN rooms r ON r.id=c.room_id JOIN contract_versions cv ON cv.contract_id=c.id AND cv.version=c.onboarding_version JOIN rental_confirmations rc ON rc.contract_version_id=cv.id AND rc.party IN ('LANDLORD','TENANT') WHERE r.property_id=:property AND c.tenant_id IS NOT NULL AND c.status NOT IN ('CANCELLED','TERMINATED') GROUP BY c.id,c.room_id,c.tenant_id,c.code,cv.id HAVING COUNT(DISTINCT rc.party)=2":"SELECT c.id,c.room_id,c.tenant_id,NULL assigned,c.created_at at_time,c.created_at,c.code,CONCAT('created-',c.id) source_key FROM contracts c JOIN rooms r ON r.id=c.room_id WHERE r.property_id=:property AND c.tenant_id IS NOT NULL AND c.status NOT IN ('DRAFT','CANCELLED','TERMINATED')";}
   case "CONTRACT_EXPIRY"->{type="CONTRACT";category="CONTRACT";sql="SELECT c.id,c.room_id,c.tenant_id,NULL assigned,c.end_date at_time,c.created_at,c.code,CAST(c.end_date AS CHAR) source_key FROM contracts c JOIN rooms r ON r.id=c.room_id WHERE r.property_id=:property AND c.operational_ended_at IS NULL AND c.status IN ('ACTIVE','EXPIRING','EXPIRED','TERMINATION_REQUESTED')";}
   case "CHECKIN"->{type="CHECKIN";category="CONTRACT";sql="SELECT c.id,c.room_id,c.tenant_id,NULL assigned,ci.scheduled_date at_time,ci.created_at,c.code,CAST(ci.scheduled_date AS CHAR) source_key FROM rental_checkins ci JOIN contracts c ON c.id=ci.contract_id JOIN rooms r ON r.id=c.room_id WHERE r.property_id=:property AND ci.actual_checkin_at IS NULL AND ci.status NOT IN ('COMPLETED','CANCELLED') AND c.status='PENDING_CONFIRMATION'";}
   case "CHECKOUT"->{type="CHECKOUT";category="CHECKOUT";sql="SELECT c.id,c.room_id,c.tenant_id,co.handover_assignee_id assigned,COALESCE(co.inspection_scheduled_at,CAST(COALESCE(co.confirmed_date,co.requested_date) AS DATETIME)) at_time,co.created_at,c.code,CONCAT(co.id,'|',COALESCE(co.confirmed_date,co.requested_date),'|',COALESCE(CAST(co.inspection_scheduled_at AS CHAR),'')) source_key FROM rental_checkouts co JOIN contracts c ON c.id=co.contract_id JOIN rooms r ON r.id=c.room_id WHERE r.property_id=:property AND co.status NOT IN ('CANCELLED','COMPLETED') AND co.actual_checkout_at IS NULL";}
   case "DEPOSIT_REFUNDED"->{type="CONTRACT";category="PAYMENT";sql="SELECT d.contract_id id,c.room_id,d.tenant_id,NULL assigned,t.transacted_at at_time,t.transacted_at created_at,c.code,CONCAT('refund-',t.id) source_key FROM deposit_transactions t JOIN tenant_deposits d ON d.id=t.deposit_id JOIN contracts c ON c.id=d.contract_id WHERE d.property_id=:property AND t.transaction_type='REFUND' AND t.status='CONFIRMED'";}
   default->{type="MAINTENANCE";category="MAINTENANCE";String at=Set.of("MAINTENANCE_CREATED","MAINTENANCE_URGENT").contains(event)?"m.created_at":"MAINTENANCE_COMPLETED".equals(event)?"m.completed_at":"MAINTENANCE_ASSIGNED".equals(event)?"COALESCE((SELECT MAX(ma.assigned_at) FROM maintenance_assignments ma WHERE ma.maintenance_request_id=m.id AND ma.user_id=m.assigned_to AND ma.unassigned_at IS NULL),m.updated_at)":"COALESCE(m.sla_due_at,m.preferred_service_time,m.created_at)";String condition=switch(event){case "MAINTENANCE_CREATED"->"m.status NOT IN ('CANCELLED')";case "MAINTENANCE_COMPLETED"->"m.status IN ('COMPLETED','INSPECTED','CLOSED') AND m.completed_at IS NOT NULL";case "MAINTENANCE_URGENT"->"m.priority='URGENT' AND m.accepted_at IS NULL AND m.status NOT IN ('COMPLETED','CLOSED','CANCELLED')";case "MAINTENANCE_ASSIGNED"->"m.assigned_to IS NOT NULL AND m.status NOT IN ('COMPLETED','CLOSED','CANCELLED')";default->"m.status NOT IN ('COMPLETED','CLOSED','CANCELLED') AND m.sla_due_at IS NOT NULL";};sql="SELECT m.id,m.room_id,m.tenant_id,m.assigned_to assigned,"+at+" at_time,"+(Set.of("MAINTENANCE_ASSIGNED","MAINTENANCE_COMPLETED").contains(event)?at:"m.created_at")+" created_at,m.code,CONCAT(COALESCE(CAST(m.sla_due_at AS CHAR),''),'|',COALESCE(m.assigned_to,''),'|',COALESCE(CAST(m.completed_at AS CHAR),'')) source_key FROM maintenance_requests m WHERE m.property_id=:property AND "+condition;}
  }
  String label=switch(event){case "INVOICE_ISSUED"->"Hóa đơn đã phát hành";case "PAYMENT_OPEN"->"Đã mở thời gian thanh toán";case "INVOICE_BEFORE_DUE"->"Hóa đơn sắp đến hạn";case "INVOICE_DUE"->"Hóa đơn đến hạn";case "INVOICE_OVERDUE"->"Hóa đơn quá hạn, vẫn có thể thanh toán";case "PAYMENT_CONFIRMED"->"Thanh toán đã được xác nhận";case "PAYMENT_FAILED"->"Giao dịch thanh toán chưa thành công";case "CONTRACT_CREATED"->"Hợp đồng cần xác nhận";case "CONTRACT_CONFIRMED"->"Hai bên đã xác nhận hợp đồng";case "CONTRACT_EXPIRY"->"Hợp đồng sắp hết hạn";case "CHECKIN"->"Lịch chuẩn bị nhận phòng";case "CHECKOUT"->"Lịch trả phòng: chuẩn bị kiểm kê, chỉ số và quyết toán";case "DEPOSIT_REFUNDED"->"Đã ghi nhận chi hoàn cọc thực tế";case "MAINTENANCE_ASSIGNED"->"Đã phân công bảo trì";case "MAINTENANCE_COMPLETED"->"Kỹ thuật báo hoàn thành; kiểm tra bước nghiệm thu nguồn";case "MAINTENANCE_URGENT"->"Bảo trì khẩn cấp chưa tiếp nhận";case "MAINTENANCE_DUE"->"Bảo trì đến hạn xử lý";default->"Đã tiếp nhận yêu cầu bảo trì";};
  String dedup=Set.of("CONTRACT_CREATED","CONTRACT_CONFIRMED").contains(event)?" AND NOT EXISTS(SELECT 1 FROM communication_deliveries sent JOIN contracts current_contract ON current_contract.id=sent.source_id WHERE sent.source_type='CONTRACT' AND sent.source_id=event_source.id AND sent.source_key=CONCAT('ONBOARD:"+(event.equals("CONTRACT_CREATED")?"SENT":"SIGNED")+":',current_contract.onboarding_version))":"";final String sourceType=type,cat=category;return db.sql("SELECT * FROM ("+sql+") event_source WHERE (:sourceId IS NULL OR id=:sourceId)"+dedup+" ORDER BY at_time,id LIMIT 1000").param("sourceId",sourceId).param("property",property).query().listOfRows().stream().filter(r->r.get("at_time")!=null).map(r->new Source(event,sourceType,number(r,"id"),property,nullable(r,"room_id"),nullable(r,"tenant_id"),nullable(r,"assigned"),datetime(r.get("at_time")),datetime(r.get("created_at")),Objects.toString(r.get("source_key"),""),r.get("code").toString(),cat,label)).toList();
 }
 boolean eventIsHistorical(String e){return Set.of("CONTRACT_CREATED","CONTRACT_CONFIRMED","INVOICE_ISSUED","PAYMENT_CONFIRMED","PAYMENT_FAILED","MAINTENANCE_CREATED","MAINTENANCE_ASSIGNED","MAINTENANCE_COMPLETED","DEPOSIT_REFUNDED").contains(e);}
 LocalDateTime due(Source s,Map<String,Object> rule){int offset=((Number)rule.get("offset_days")).intValue();if(eventIsHistorical(s.event())||"MAINTENANCE_URGENT".equals(s.event()))return s.at();var date=s.at().toLocalDate();if("INVOICE_OVERDUE".equals(s.event())){date=date.plusDays(Math.max(1,offset));LocalDate enabledDate=datetime(rule.get("effective_from")).toLocalDate();if(date.isBefore(enabledDate))date=enabledDate;}else if("MAINTENANCE_DUE".equals(s.event()))date=date.minusDays(offset);else date=date.minusDays(offset);return date.atTime(((Number)rule.get("send_hour")).intValue(),0);}
 boolean eligible(Source s,Map<String,Object> rule,LocalDateTime at){if(eventIsHistorical(s.event())&&s.created()!=null&&s.created().isBefore(datetime(rule.get("effective_from"))))return false;LocalDateTime due=due(s,rule);return !due.isBefore(at.minusDays(7))&&!due.isAfter(at.plusDays(60));}
 List<Long> recipients(Source s,Map<String,Object> rule){String audience=rule.get("audience").toString();var actual=service.recipients(s.property());if("TENANT".equals(audience))return s.tenant()!=null&&db.sql("SELECT COUNT(*) FROM users WHERE id=:id AND status='ACTIVE'").param("id",s.tenant()).query(Long.class).single()==1?List.of(s.tenant()):List.of();if("ASSIGNEE".equals(audience))return s.assignee()!=null&&actual.stream().anyMatch(r->number(r,"id")==s.assignee()&&!"TENANT".equals(r.get("recipient_role")))?List.of(s.assignee()):List.of();return actual.stream().filter(r->Set.of("OWNER","MANAGER").contains(r.get("recipient_role"))).map(r->number(r,"id")).distinct().toList();}
 AuthenticatedUser actor(long id,String role){return new AuthenticatedUser(id,"communication-worker",RoleCode.valueOf(role));}
 boolean activeActor(AuthenticatedUser actor){return db.sql("SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.id=:id AND u.status='ACTIVE' AND r.code=:role").param("id",actor.id()).param("role",actor.activeRole().name()).query(Long.class).single()==1;}
 AuthenticatedUser ruleActor(Map<String,Object> rule){long id=number(rule,"created_by");String role=db.sql("SELECT CASE WHEN p.owner_id=:id THEN 'OWNER' WHEN EXISTS(SELECT 1 FROM property_managers WHERE property_id=p.id AND manager_id=:id) THEN 'MANAGER' ELSE 'ACCOUNTANT' END FROM properties p WHERE p.id=:property").param("id",id).param("property",rule.get("property_id")).query(String.class).single();return actor(id,role);}
 @Transactional(isolation=Isolation.READ_COMMITTED) public int scan(LocalDateTime at){int count=0;var rules=db.sql("SELECT * FROM communication_rules WHERE enabled=TRUE ORDER BY last_scanned_at,id LIMIT 100 FOR UPDATE SKIP LOCKED").query().listOfRows();for(var rule:rules){db.sql("UPDATE communication_rules SET last_scanned_at=:at WHERE id=:id").param("at",at).param("id",rule.get("id")).update();try{String event=rule.get("event_type").toString();service.manage(ruleActor(rule),number(rule,"property_id"),event.startsWith("INVOICE")||event.startsWith("PAYMENT")||"DEPOSIT_REFUNDED".equals(event));if(activeActor(ruleActor(rule))){for(var s:sources(number(rule,"property_id"),event)){if(!eligible(s,rule,at))continue;for(long recipient:recipients(s,rule)){String key=hash("AUTO|"+rule.get("id")+"|"+s.type()+"|"+s.id()+"|"+s.key()+"|"+recipient+"|IN_APP");count+=db.sql("INSERT INTO communication_deliveries(rule_id,property_id,recipient_id,channel,category,title,body,source_type,source_id,source_key,business_key,status,scheduled_at,next_attempt_at) VALUES(:rule,:property,:recipient,'IN_APP',:category,:title,:body,:type,:source,:sourceKey,:key,'SCHEDULED',:at,:at) ON DUPLICATE KEY UPDATE id=id").param("rule",rule.get("id")).param("property",s.property()).param("recipient",recipient).param("category",s.category()).param("title",s.title()).param("body",sourceBody(s)).param("type",s.type()).param("source",s.id()).param("sourceKey",s.key()).param("key",key).param("at",due(s,rule)).update();}}var pending=db.sql("SELECT * FROM communication_deliveries WHERE rule_id=:id AND status IN ('QUEUED','SCHEDULED','FAILED') ORDER BY id LIMIT 25 FOR UPDATE SKIP LOCKED").param("id",rule.get("id")).query().listOfRows();for(var queued:pending){boolean valid=sources(number(rule,"property_id"),event,number(queued,"source_id")).stream().anyMatch(source->source.key().equals(queued.get("source_key"))&&eligible(source,rule,at)&&recipients(source,rule).contains(number(queued,"recipient_id")));if(!valid)finish(number(queued,"id"),"CANCELLED","SOURCE_OR_SCOPE_CHANGED",at);}}}catch(com.thangit.boardinghouse.common.exception.AuthException ignored){/* Revoked rule owners cannot enqueue. No private content is logged. */}}if(emailReminders)count+=enqueueReminderEmail();if(external.independentWorker())count+=enqueueIntegratedChannels();return count;}
 String sourceBody(Source source){
  if("PAYMENT_FAILED".equals(source.event()))return source.title()+" | "+source.code()+" | Hóa đơn chưa được tất toán bởi giao dịch này; hãy kiểm tra công nợ hiện tại trước khi thử lại.";
  if("INVOICE".equals(source.type())){var rows=db.sql("SELECT i.code,i.billing_period,i.due_date,i.total_amount,i.remaining_amount,r.code room_code,u.full_name FROM invoices i JOIN rooms r ON r.id=i.room_id JOIN users u ON u.id=i.tenant_id WHERE i.id=:id").param("id",source.id()).query().listOfRows();
   if(!rows.isEmpty()){var invoice=rows.getFirst();return source.title()+" | "+invoice.get("full_name")+" | "+invoice.get("code")+" | "+invoice.get("room_code")+" | "+invoice.get("billing_period")+" | Total VND: "+invoice.get("total_amount")+" | Outstanding VND: "+invoice.get("remaining_amount")+" | Due: "+invoice.get("due_date");}}
  return source.title()+" | "+source.code()+" | "+source.at();
 }
 int enqueueIntegratedChannels(){return db.sql("""
  INSERT INTO communication_deliveries(rule_id,property_id,recipient_id,channel,category,title,body,source_type,source_id,source_key,business_key,status,scheduled_at,next_attempt_at)
  SELECT d.rule_id,d.property_id,d.recipient_id,c.kind,d.category,d.title,d.body,d.source_type,d.source_id,d.source_key,SHA2(CONCAT(c.kind,'|',d.business_key),256),'SCHEDULED',d.scheduled_at,d.scheduled_at
  FROM communication_deliveries d JOIN communication_rules r ON r.id=d.rule_id JOIN properties p ON p.id=d.property_id
  JOIN integration_configs c ON c.owner_id=p.owner_id AND c.enabled=TRUE AND c.kind IN ('EMAIL','ZALO','WEB_PUSH')
  WHERE d.channel='IN_APP' AND r.enabled=TRUE AND (
   c.kind='EMAIL' AND EXISTS(SELECT 1 FROM notification_preferences n WHERE n.user_id=d.recipient_id AND n.email_enabled=TRUE)
   OR c.kind='ZALO' AND EXISTS(SELECT 1 FROM notification_preferences n WHERE n.user_id=d.recipient_id AND n.zalo_enabled=TRUE)
   OR c.kind='WEB_PUSH' AND EXISTS(SELECT 1 FROM web_push_subscriptions w WHERE w.user_id=d.recipient_id AND w.owner_id=p.owner_id AND w.enabled=TRUE))
  ON DUPLICATE KEY UPDATE id=communication_deliveries.id
  """).update();}
 int enqueueReminderEmail(){return db.sql("""
  INSERT INTO communication_deliveries(rule_id,property_id,recipient_id,channel,category,title,body,source_type,source_id,source_key,business_key,status,scheduled_at,next_attempt_at)
  SELECT d.rule_id,d.property_id,d.recipient_id,'EMAIL',d.category,d.title,d.body,d.source_type,d.source_id,d.source_key,SHA2(CONCAT('EMAIL|',d.business_key),256),'SCHEDULED',d.scheduled_at,d.scheduled_at
  FROM communication_deliveries d JOIN communication_rules r ON r.id=d.rule_id
  WHERE d.channel='IN_APP' AND r.enabled=TRUE AND r.event_type IN ('INVOICE_ISSUED','INVOICE_BEFORE_DUE','INVOICE_DUE','INVOICE_OVERDUE','PAYMENT_CONFIRMED')
  ON DUPLICATE KEY UPDATE id=communication_deliveries.id
  """).update();}
 void lockSource(Map<String,Object>d){String table=switch(Objects.toString(d.get("source_type"),"")){case "INVOICE"->"invoices";case "CONTRACT","CHECKIN","CHECKOUT"->"contracts";case "MAINTENANCE"->"maintenance_requests";default->null;};if(table!=null)db.sql("SELECT id FROM "+table+" WHERE id=:id FOR UPDATE").param("id",d.get("source_id")).query(Long.class).optional();}
 boolean current(Map<String,Object>d,LocalDateTime at){long property=number(d,"property_id"),recipient=number(d,"recipient_id");if(!"ACTIVE".equals(db.sql("SELECT status FROM users WHERE id=:id FOR UPDATE").param("id",recipient).query(String.class).single()))return false;db.sql("SELECT u.id FROM users u JOIN properties p ON p.owner_id=u.id WHERE p.id=:id FOR UPDATE").param("id",property).query(Long.class).single();if(d.get("rule_id")!=null){var rows=db.sql("SELECT * FROM communication_rules WHERE id=:id").param("id",d.get("rule_id")).query().listOfRows();if(rows.isEmpty()||!Boolean.TRUE.equals(rows.getFirst().get("enabled")))return false;var rule=rows.getFirst();if(!activeActor(ruleActor(rule)))return false;String e=rule.get("event_type").toString();try{service.manage(ruleActor(rule),property,e.startsWith("INVOICE")||e.startsWith("PAYMENT")||e.equals("DEPOSIT_REFUNDED"));}catch(com.thangit.boardinghouse.common.exception.AuthException ex){return false;}lockSource(d);return sources(property,e,number(d,"source_id")).stream().anyMatch(s->s.id()==number(d,"source_id")&&s.key().equals(d.get("source_key"))&&eligible(s,rule,at)&&!due(s,rule).isAfter(at)&&recipients(s,rule).contains(recipient));}
  if("CONTRACT".equals(d.get("source_type"))&&Objects.toString(d.get("source_key"),"").startsWith("ONBOARD:"))return ContractDeliveryService.current(db,d);
  if("TASK".equals(d.get("source_type"))){var tasks=db.sql("SELECT * FROM operational_tasks WHERE id=:id FOR UPDATE").param("id",d.get("source_id")).query().listOfRows();return !tasks.isEmpty()&&number(tasks.getFirst(),"assignee_id")==recipient&&Long.toString(number(tasks.getFirst(),"version")).equals(d.get("source_key"));}
  var c=db.sql("SELECT * FROM communication_campaigns WHERE id=:id").param("id",d.get("campaign_id")).query().singleRow();if("CANCELLED".equals(c.get("status"))||!activeActor(actor(number(c,"created_by"),c.get("actor_role").toString())))return false;try{service.manage(actor(number(c,"created_by"),c.get("actor_role").toString()),property,service.financeCategory(c.get("category").toString()));}catch(com.thangit.boardinghouse.common.exception.AuthException ex){return false;}try{var message=service.json.readValue(c.get("payload").toString(),CommunicationService.Message.class);return service.selected(actor(number(c,"created_by"),c.get("actor_role").toString()),message).stream().anyMatch(r->number(r,"id")==recipient);}catch(Exception changed){return false;}
 }
 static LocalTime localTime(Object value){return value==null?null:value instanceof LocalTime t?t:value instanceof java.sql.Time t?t.toLocalTime():LocalTime.parse(value.toString());}
 boolean quiet(long recipient,LocalDateTime at,String category){var prefs=db.sql("SELECT * FROM notification_preferences WHERE user_id=:id").param("id",recipient).query().listOfRows();if(prefs.isEmpty())return false;var p=prefs.getFirst();if(!Set.of("INVOICE","CONTRACT","EMERGENCY","SYSTEM").contains(category)&&p.get("category_preferences")!=null)try{var choices=service.json.readTree(p.get("category_preferences").toString());if(choices.has(category)&&!choices.path(category).asBoolean())return true;}catch(Exception ignored){}if(!Boolean.TRUE.equals(p.get("quiet_hours_enabled")))return false;LocalTime start=localTime(p.get("quiet_hours_start")),end=localTime(p.get("quiet_hours_end")),time=at.toLocalTime();if(start==null||end==null||start.equals(end))return false;return start.isBefore(end)?!time.isBefore(start)&&time.isBefore(end):!time.isBefore(start)||time.isBefore(end);}
 @Transactional(isolation=Isolation.READ_COMMITTED) public int deliver(LocalDateTime at){int done=0;var candidates=db.sql("SELECT id FROM communication_deliveries WHERE "+(external.independentWorker()?"channel='IN_APP' AND ":"")+"status IN ('SCHEDULED','QUEUED','FAILED') AND next_attempt_at<=:at AND attempt_count<3 AND (status<>'FAILED' OR retryable=TRUE) ORDER BY next_attempt_at,id LIMIT 100").param("at",at).query(Long.class).list();if(candidates.isEmpty())return 0;var rows=db.sql("SELECT * FROM communication_deliveries FORCE INDEX(PRIMARY) WHERE id IN (:ids) AND status IN ('SCHEDULED','QUEUED','FAILED') AND next_attempt_at<=:at AND attempt_count<3 AND (status<>'FAILED' OR retryable=TRUE) ORDER BY id LIMIT 25 FOR UPDATE SKIP LOCKED").param("ids",candidates).param("at",at).query().listOfRows();var userLocks=new TreeSet<Long>();for(var row:rows){userLocks.add(number(row,"recipient_id"));userLocks.add(db.sql("SELECT owner_id FROM properties WHERE id=:id").param("id",row.get("property_id")).query(Long.class).single());}if(!userLocks.isEmpty())db.sql("SELECT id FROM users WHERE id IN (:ids) ORDER BY id FOR UPDATE").param("ids",userLocks).query(Long.class).list();for(var d:rows){long id=number(d,"id"),recipient=number(d,"recipient_id");if(!current(d,at)){finish(id,"CANCELLED","SOURCE_OR_SCOPE_CHANGED",at);continue;}if(quiet(recipient,at,d.get("category").toString())){db.sql("UPDATE communication_deliveries SET next_attempt_at=:next WHERE id=:id").param("next",at.plusHours(1)).param("id",id).update();continue;}int limit=d.get("rule_id")==null?5:db.sql("SELECT daily_limit FROM communication_rules WHERE id=:id").param("id",d.get("rule_id")).query(Integer.class).single();long sent=db.sql("SELECT COUNT(*) FROM communication_deliveries WHERE recipient_id=:recipient AND property_id=:property AND channel=:channel AND finished_at>=:day AND finished_at<:end AND status IN ('DELIVERED','SENT')").param("recipient",recipient).param("property",d.get("property_id")).param("channel",d.get("channel")).param("day",at.toLocalDate().atStartOfDay()).param("end",at.toLocalDate().plusDays(1).atStartOfDay()).query(Long.class).single();if(sent>=limit){db.sql("UPDATE communication_deliveries SET next_attempt_at=:next WHERE id=:id").param("next",at.toLocalDate().plusDays(1).atTime(9,0)).param("id",id).update();continue;}
   int attempt=((Number)d.get("attempt_count")).intValue()+1;db.sql("UPDATE communication_deliveries SET status='SENDING',attempt_count=:attempt WHERE id=:id").param("attempt",attempt).param("id",id).update();CommunicationSender.Result result;
   if("IN_APP".equals(d.get("channel"))){long notification=service.insert("INSERT INTO notifications(user_id,title,content,type,category,summary,property_id,reference_type,reference_id,communication_delivery_id) VALUES(:recipient,:title,:body,:category,:category,:summary,:property,:type,:source,:id)",new HashMap<>(){{put("recipient",recipient);put("title",d.get("title"));put("body",d.get("body"));put("category",d.get("category"));put("summary",d.get("body").toString().substring(0,Math.min(500,d.get("body").toString().length())));put("property",d.get("property_id"));put("type",d.get("source_type"));put("source",d.get("source_id"));put("id",id);}});db.sql("UPDATE communication_deliveries SET notification_id=:notification WHERE id=:id").param("notification",notification).param("id",id).update();result=new CommunicationSender.Result("DELIVERED","INBOX_AVAILABLE","INBOX-"+notification,false);}else try{result=external.send(number(d,"property_id"),d.get("channel").toString(),d.get("business_key").toString(),recipient,d.get("title").toString(),d.get("body").toString());}catch(RuntimeException unavailable){result=new CommunicationSender.Result("FAILED","PROVIDER_EXCEPTION",null,true);}
   if(!Set.of("FAILED","UNKNOWN","SIMULATED","SENT","DELIVERED").contains(result.outcome()))throw new IllegalStateException("Unsupported provider outcome");String code=result.code()!=null&&result.code().matches("[A-Z0-9_]{1,80}")?result.code():"PROVIDER_ERROR";String reference=result.providerReference()!=null&&result.providerReference().matches("[a-zA-Z0-9_:-]{1,180}")?result.providerReference():null;boolean retry=result.retryable()&&"FAILED".equals(result.outcome())&&attempt<3;db.sql("INSERT INTO communication_attempts(delivery_id,attempt_number,outcome,result_code,provider_reference,attempted_at) VALUES(:id,:attempt,:outcome,:code,:reference,:at)").param("id",id).param("attempt",attempt).param("outcome",result.outcome()).param("code",code).param("reference",reference).param("at",at).update();db.sql("UPDATE communication_deliveries SET status=:status,result_code=:code,provider_reference=:reference,retryable=:retry,next_attempt_at=:next,finished_at=:at WHERE id=:id").param("status",result.outcome()).param("code",code).param("reference",reference).param("retry",retry).param("next",at.plusMinutes(attempt==1?1:5)).param("at",at).param("id",id).update();done++;
  }return done;}
 void finish(long id,String status,String code,LocalDateTime at){db.sql("UPDATE communication_deliveries SET status=:status,result_code=:code,retryable=FALSE,finished_at=:at WHERE id=:id").param("status",status).param("code",code).param("at",at).param("id",id).update();}
 public Object calendar(AuthenticatedUser p,Long property,LocalDate from,LocalDate to){if(from==null||to==null||to.isBefore(from)||to.isAfter(from.plusDays(93)))throw bad("Lịch cần khoảng ngày tối đa 93 ngày.");var ids=service.properties(p);if(property!=null){service.property(p,property);ids=List.of(property);}List<Map<String,Object>> out=new ArrayList<>();boolean staff=Set.of(RoleCode.OWNER,RoleCode.MANAGER).contains(p.activeRole());for(long prop:ids){for(String e:List.of("CONTRACT_EXPIRY","CHECKIN","CHECKOUT","MAINTENANCE_DUE","INVOICE_DUE")){if(p.activeRole()==RoleCode.TECHNICIAN&&!e.startsWith("MAINTENANCE"))continue;if(p.activeRole()==RoleCode.ACCOUNTANT&&!e.equals("INVOICE_DUE"))continue;if(e.equals("INVOICE_DUE")&&p.activeRole()==RoleCode.MANAGER&&db.sql("SELECT COUNT(*) FROM manager_property_capabilities WHERE property_id=:property AND manager_id=:actor AND capability='FINANCE_READ'").param("property",prop).param("actor",p.id()).query(Long.class).single()==0)continue;for(var s:sources(prop,e)){if(s.at().toLocalDate().isBefore(from)||s.at().toLocalDate().isAfter(to))continue;if(p.activeRole()==RoleCode.TENANT&&!Objects.equals(s.tenant(),p.id()))continue;if(p.activeRole()==RoleCode.TECHNICIAN&&!Objects.equals(s.assignee(),p.id()))continue;out.add(Map.of("id",s.type()+"-"+s.id(),"title",s.title()+" · "+s.code(),"starts_at",s.at(),"due_at",s.at(),"kind","SOURCE","source_type",s.type(),"link",link(p.activeRole(),s.type(),s.id()),"status","SOURCE","property_id",prop));}}}
  String query="SELECT t.*,u.full_name assignee_name FROM operational_tasks t JOIN users u ON u.id=t.assignee_id WHERE t.property_id IN (:ids) AND t.starts_at<:end AND t.due_at>=:start"+(staff?"":" AND t.assignee_id=:actor")+" ORDER BY t.due_at,t.id LIMIT 1000";var tasks=db.sql(query).param("ids",service.safe(ids)).param("start",from.atStartOfDay()).param("end",to.plusDays(1).atStartOfDay()).param("actor",p.id()).query().listOfRows();for(var t:tasks){t.put("kind","MANUAL");t.put("link","");out.add(t);}out.sort(Comparator.comparing(x->datetime(x.get("due_at"))));return Map.of("rows",out,"dueTasks",tasks.stream().filter(t->!Set.of("COMPLETED","CANCELLED").contains(t.get("status"))&&datetime(t.get("due_at")).isBefore(now().plusDays(1))).count(),"overdueTasks",tasks.stream().filter(t->!Set.of("COMPLETED","CANCELLED").contains(t.get("status"))&&datetime(t.get("due_at")).isBefore(now())).count(),"sourceLimitPerType",1000);}
}
